 "content": "def transform(grid):
    """Connect aligned 1 markers; extend each 6 along its NW-SE diagonal."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    # Join pairs of 1 markers that lie on a 45-degree diagonal.
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if abs(dr) == abs(dc) and dr != 0:
                sr, sc = (1 if dr > 0 else -1), (1 if dc > 0 else -1)
                r, c = r1, c1
                while True:
                    if grid[r][c] != 6:
                        out[r][c] = 1
                    if (r, c) == (r2, c2):
                        break
                    r += sr
                    c += sc

    # Each 6 marks a full NW-SE diagonal across the grid.
    for r0, c0 in sixes:
        r, c = r0, c0
        while r > 0 and c > 0:
            r -= 1
            c -= 1
        while r < h and c < w:
            out[r][c] = 6
            r += 1
            c += 1
    return out
